        "explanation": "Marking Scheme & Analysis:\nMarking Scheme:\n• Aspirational Dimension  [2 Marks] :\n- Represents Sophie's yearning for social mobility, fame, and escape from\nworking-class monotony.\n- Embodies adolescent hopes of achieving success and stepping into\nglamour.\n• Ironic Dimension  [2 Marks] :\n- In reality, Sophie is going nowhere: her socioeconomic circumstances\nconﬁne her to the local factory.\n- Her journey to the canal ends in a lonely bench under a dark tree, unable\nto escape her predetermined life.\n• Synthesis  [1 Mark] : Highlights the tragic gap between grand youthful\ndreams and the unyielding constraints of social class."
