        "explanation": "Marking Scheme & Analysis:\nMarking Scheme:\n• (a) Context  [1.5 Marks] : Sophie is sitting on a wooden bench beneath an\nelm tree along a secluded canal path, waiting for Danny Casey to deliver a\npromised autograph.\n• (b) Heartbreaking Realization  [1.5 Marks] : She confronts the cold truth\nthat Danny Casey will never arrive; the entire date was an imaginary\ncreation.\n• (c) Inner Conﬂict\n[2 Marks]\n: Illustrates the painful collision between her\nneed for fantasy and the inescapable reality of her working-class life. She\nmourns not just an absent athlete, but the collapse of her romanticized\nself-worth."
