        "tag": "CBSE 2022",
        "question": "[ARTICLE WRITING - 5 Marks / 120-150 Words]\nPlastic pollution has choked our oceans, degraded terrestrial soil, and\nentered the human food chain through microplastics. Write an article for\na national daily on 'Dismantling the Single-Use Plastic Menace: From\nPolicy to Practice'. You are Aarav/Aanya of Class XII.\n[5 Marks]",
        "answer": "Complete 150-word article on combating single-use plastic pollution.",
        "explanation": "Marking Scheme & Analysis:\nMarking Scheme:\n• Format  [1 Mark] : Catchy Heading and Byline.\n• Content  [2 Marks] : Scale of plastic crisis, microplastics in food chain,\nindividual and policy solutions.\n• Organization\n[1 Mark]\n: Coherent multi-paragraph ﬂow.\n• Accuracy  [1 Mark] : Persuasive rhetoric, vocabulary.\n[SOLVED MODEL]:\nDISMANTLING THE SINGLE-USE PLASTIC MENACE\nBy Aarav Singhal, Class XII\nIn our modern consumer society, single-use plastic has become an\necological catastrophe. Conceived for short-term human convenience, this\nindestructible synthetic polymer persists in the biosphere for centuries,\nclogging urban drainage, choking water bodies, and turning fertile\nagricultural lands into toxic wastelands.\nThe crisis has breached our biological defenses: recent marine and\nmedical studies reveal that microplastics have entered the marine food\nchain and human bloodstream, posing grave oncological and endocrine\nthreats. Despite legislative bans on single-use polythene bags and straws,\nweak enforcement and the absence of cheap biodegradable substitutes\nallow the scourge to proliferate unchecked.\nTackling this menace demands aggressive systemic reform. Municipalities\nmust enforce zero-tolerance penalties on non-compliant manufacturers\nwhile incentivizing biodegradable alternatives like bamboo, hemp, and jute.\nOn an individual level, citizens must embrace cloth tote bags, stainless-\nsteel containers, and refuse disposable packaging. We cannot continue\ntrading the long-term survival of our planet for ﬁve minutes of plastic\nconvenience.\nCBSE Class 12 English Core (Code 301) — Master PYQ Bank (2015–2024)\nStrictly compliant with CBSE Examination Curriculum, 80-Mark Theory Pattern, and Oﬃcial\nStep-by-Step Marking Schemes."
